from pathlib import Path

import matplotlib.pyplot as plt
import numpy as np

from benchmark_runner import BenchmarkResult


class PlotMaker:
    """Creates plots from benchmark results."""

    def __init__(self, results: list[BenchmarkResult], output_dir: str = "results"):
        self.results = results
        self.output_dir = Path(output_dir)
        self.output_dir.mkdir(parents=True, exist_ok=True)

    def _group_by_calculator(self) -> dict[str, list[BenchmarkResult]]:
        """Group results by calculator name."""
        grouped: dict[str, list[BenchmarkResult]] = {}
        for r in self.results:
            grouped.setdefault(r.calculator_name, []).append(r)
        return grouped

    def plot_time_vs_resolution(self, save: bool = True, show: bool = False) -> plt.Figure:
        """Line plot: execution time vs resolution for each calculator."""
        fig, ax = plt.subplots(figsize=(10, 6))
        grouped = self._group_by_calculator()

        for name, results in grouped.items():
            results.sort(key=lambda r: r.resolution)
            resolutions = [r.resolution for r in results]
            means = [r.mean_time for r in results]
            stds = [r.std_time for r in results]

            ax.errorbar(resolutions, means, yerr=stds, marker='o', capsize=4, label=name)

        ax.set_xlabel("Resolution (pixels)")
        ax.set_ylabel("Time (seconds)")
        ax.set_title("Mandelbrot Computation Time vs Resolution")
        ax.legend()
        ax.grid(True, alpha=0.3)
        ax.set_xscale('log', base=2)
        ax.set_yscale('log')

        plt.tight_layout()
        if save:
            fig.savefig(self.output_dir / "time_vs_resolution.png", dpi=150)
        if show:
            plt.show()
        return fig

    def plot_speedup(self, baseline: str = "NativeCalculator", save: bool = True, show: bool = False) -> plt.Figure:
        """Bar chart: speedup relative to baseline at each resolution."""
        grouped = self._group_by_calculator()

        if baseline not in grouped:
            raise ValueError(f"Baseline '{baseline}' not found in results. Available: {list(grouped.keys())}")

        baseline_results = {r.resolution: r.mean_time for r in grouped[baseline]}

        fig, ax = plt.subplots(figsize=(10, 6))
        other_calcs = [name for name in grouped if name != baseline]
        x = np.arange(len(baseline_results))
        width = 0.8 / max(len(other_calcs), 1)

        resolutions = sorted(baseline_results.keys())

        for i, name in enumerate(other_calcs):
            calc_times = {r.resolution: r.mean_time for r in grouped[name]}
            speedups = [baseline_results[res] / calc_times[res] for res in resolutions if res in calc_times]
            offset = (i - len(other_calcs) / 2 + 0.5) * width
            ax.bar(x[:len(speedups)] + offset, speedups, width, label=name)

        ax.set_xlabel("Resolution")
        ax.set_ylabel(f"Speedup vs {baseline}")
        ax.set_title(f"Speedup Relative to {baseline}")
        ax.set_xticks(x)
        ax.set_xticklabels([f"{r}x{r}" for r in resolutions])
        ax.legend()
        ax.grid(True, alpha=0.3, axis='y')
        ax.axhline(y=1, color='gray', linestyle='--', alpha=0.5)

        plt.tight_layout()
        if save:
            fig.savefig(self.output_dir / "speedup.png", dpi=150)
        if show:
            plt.show()
        return fig

    def plot_scaling(self, save: bool = True, show: bool = False) -> plt.Figure:
        """Log-log plot showing how each calculator scales with problem size."""
        fig, ax = plt.subplots(figsize=(10, 6))
        grouped = self._group_by_calculator()

        for name, results in grouped.items():
            results.sort(key=lambda r: r.resolution)
            pixels = [r.resolution ** 2 for r in results]
            means = [r.mean_time for r in results]
            ax.plot(pixels, means, marker='s', label=name)

        ax.set_xlabel("Total pixels (width × height)")
        ax.set_ylabel("Time (seconds)")
        ax.set_title("Scaling: Time vs Problem Size")
        ax.legend()
        ax.grid(True, alpha=0.3)
        ax.set_xscale('log')
        ax.set_yscale('log')

        plt.tight_layout()
        if save:
            fig.savefig(self.output_dir / "scaling.png", dpi=150)
        if show:
            plt.show()
        return fig

    def make_all_plots(self, save: bool = True, show: bool = False):
        """Generate all available plots."""
        self.plot_time_vs_resolution(save=save, show=show)
        self.plot_speedup(save=save, show=show)
        self.plot_scaling(save=save, show=show)
        if save:
            print(f"Plots saved to {self.output_dir}/")
